css:
[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-canvas]{background-image:linear-gradient(rgba(255,255,255,.13) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.13) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.055) 1px,transparent 1px)!important;background-size:120px 120px,120px 120px,24px 24px,24px 24px!important}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{font-family:ui-monospace,"SF Mono",Menlo,Consolas,monospace;text-transform:uppercase;letter-spacing:.06em}
[data-user-message-bubble]{box-shadow:inset 0 0 0 1px rgba(255,255,255,.4);outline:1px dashed rgba(255,255,255,.25);outline-offset:4px}
::selection{background:rgba(255,255,255,.25)}
